/**
 * Knowledge Base for ICEwhistle
 * Contains verified legal information, resources, and guidance
 * All content is pre-vetted to prevent hallucination risks
 */

export interface KnowledgeEntry {
  id: string
  category: 'rights' | 'resources' | 'legal' | 'emergency' | 'vulnerable' | 'detention' | 'workplace'
  title: string
  titleEs?: string  // Spanish translation
  titlePt?: string  // Portuguese translation
  content: string
  contentEs?: string  // Spanish translation
  contentPt?: string  // Portuguese translation
  keywords: string[]
  keywordsEs?: string[]  // Spanish keywords for search
  keywordsPt?: string[]  // Portuguese keywords for search
  languages?: string[]
  urls?: string[]
  phones?: string[]
  priority?: number // Higher = more important for search ranking
}

// Helper to get translated content based on language
export function getTranslatedEntry(entry: KnowledgeEntry, language: 'en' | 'es' | 'pt') {
  return {
    ...entry,
    title: language === 'es' ? (entry.titleEs || entry.title)
         : language === 'pt' ? (entry.titlePt || entry.title)
         : entry.title,
    content: language === 'es' ? (entry.contentEs || entry.content)
           : language === 'pt' ? (entry.contentPt || entry.content)
           : entry.content,
  }
}

